static fromText(text) {
  const calendar = new Calendar();
  const lines = text.split('\n');

  lines.forEach(line => {
    const [timeRange, id] = line.split(' ');
    if (!timeRange || !id) {
      throw new Error('Malformed line');
    }

    const [startTime, endTime] = timeRange.split('-');
    const [startHour, startMinute] = startTime.split(':').map(Number);
    const [endHour, endMinute] = endTime.split(':').map(Number);

    const start = startHour * 60 + startMinute;
    const end = endHour * 60 + endMinute;

    if (start < 0 || start >= 1440 || end <= start || end > 1440) {
      throw new Error('Invalid start or end time');
    }

    if (calendar.meetings.some(meeting => meeting.id === id)) {
      throw new Error('Duplicate ID');
    }

    if (calendar.meetings.some(meeting => meeting.start < end && start < meeting.end)) {
      throw new Error('Overlap detected');
    }

    calendar.meetings.push({ id, start, end });
  });

  return calendar;
}

